	/*
     * @param	event CreateDimensionEvent
     */
    @EventHandler( payloadType=CreateDimensionEvent.class )
    public void handle( CreateDimensionEvent event) {
	    LOGGER.info("handling CreateDimensionEvent - " + event );
	    Dimension entity = new Dimension();
            entity.setDimensionId( event.getDimensionId() );
            entity.setName( event.getName() );
            entity.setTypeTime( event.getTypeTime() );
            entity.setDimensionType( event.getDimensionType() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllDimension( entity );
    }

    /*
     * @param	event UpdateDimensionEvent
     */
    @EventHandler( payloadType=UpdateDimensionEvent.class )
    public void handle( UpdateDimensionEvent event) {
    	LOGGER.info("handling UpdateDimensionEvent - " + event );
    	
	    Dimension entity = new Dimension();
            entity.setDimensionId( event.getDimensionId() );
            entity.setName( event.getName() );
            entity.setTypeTime( event.getTypeTime() );
            entity.setSemanticModel( event.getSemanticModel() );
            entity.setDatasets( event.getDatasets() );
            entity.setGlossaryTerms( event.getGlossaryTerms() );
            entity.setDimensionType( event.getDimensionType() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindDimension( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllDimension( entity );        
    }
    
