    /**
     * Method to retrieve the Dimension via an DimensionPrimaryKey.
     * @param 	id Long
     * @return 	Dimension
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Dimension handle( FindDimensionQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getDimensionId() );
    }
    
    /**
     * Method to retrieve a collection of all Dimensions
     *
     * @param	query	FindAllDimensionQuery 
     * @return 	List<Dimension> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Dimension> handle( FindAllDimensionQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindDimension,
 * but only if the id matches
 *
 * @param		entity	Dimension
 */
	protected void emitFindDimension( Dimension entity ) {
		LOGGER.info("handling emitFindDimension" );
		
	    queryUpdateEmitter.emit(FindDimensionQuery.class,
	                            query -> query.getFilter().getDimensionId().equals(entity.getDimensionId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllDimension
	 * 
	 * @param		entity	Dimension
	 */
	protected void emitFindAllDimension( Dimension entity ) {
		LOGGER.info("handling emitFindAllDimension" );
		
	    queryUpdateEmitter.emit(FindAllDimensionQuery.class,
	                            query -> true,
	                            entity);
	}

